id-template-columns:1fr}.fiat-summary{align-items:flex-start;gap:12px}.fiat-summary__icon{width:48px;height:48px;flex-basis:48px;border-radius:14px;font-size:23px}.fiat-summary p{flex-wrap:wrap;gap:5px 8px}.fiat-summary strong{font-size:28px;overflow-wrap:anywhere}.proof-files li{grid-template-columns:40px minmax(0,1fr)}.proof-files__actions{grid-column:1/-1;justify-content:flex-end}}
</style>
